  static ArcBlueprintResearchEntry? forBlueprintOnMap(
    String blueprintId,
    String mapId,
  ) {
    final normalizedBlueprintId = blueprintId.trim().toLowerCase();
    final normalizedMapId = mapId.trim().toLowerCase();
    for (final entry in entries) {
      if (entry.blueprintId == normalizedBlueprintId &&
          entry.mapId == normalizedMapId) {
        return entry;
      }
    }
    return null;
  }

  static List<ArcBlueprintResearchEntry> forMap(String mapId) {
    final normalized = mapId.trim().toLowerCase();
    return List<ArcBlueprintResearchEntry>.unmodifiable(
      entries.where((entry) => entry.mapId == normalized),
    );
  }

  static List<ArcBlueprintResearchEntry> forBlueprint(String blueprintId) {
    final normalized = blueprintId.trim().toLowerCase();
    return List<ArcBlueprintResearchEntry>.unmodifiable(
      entries.where((entry) => entry.blueprintId == normalized),
    );
  }
}
